def norm(s):return re.sub(r'\s+',' ',re.sub(r'[-_/]', ' ',s.casefold())).strip()
def main():
    path=ROOT/'data/curriculum.json';words=json.loads(path.read_text(encoding='utf-8'));pictograms=json.loads((ROOT/'data/arasaac_candidates.json').read_text(encoding='utf-8'));idx={}
    for p in pictograms:
        if p.get('sex') or p.get('violence'):continue
        for k in p['keywords']:idx.setdefault(norm(k['keyword']),[]).append((p,k))
    resolved=0
    for w in words:
        if w['image']:continue
        key=norm(w['english']);choices=[key,'to '+key,key+'s',key+'es',key[:-1]+'ies' if key.endswith('y') else key,'a '+key,'an '+key]
        if key in ALIASES:choices.append(norm(ALIASES[key]))
        match=next((s for s in choices if s in idx),None)
        if not match:continue
        def score(item):
            p,k=item;types={1:'verb',2:'noun',3:'adjective',4:'adverb'};pos=types.get(k.get('type'),'');tags=' '.join(p.get('categories',[])+p.get('tags',[])).lower();return (pos==w['pos'],sum(part.lower() in tags for part in w['category'].split() if len(part)>3),not p.get('schematic',False),p.get('downloads',0))
        p,k=max(idx[match],key=score)
        w.update(image_candidate=p['_id'],image_match=match,image_review='Editorial keyword/alias candidate; review the selected sense before publication.');resolved+=1
    path.write_text(json.dumps(words,ensure_ascii=False,indent=2),encoding='utf-8');missing=[w['english'] for w in words if not w['image'] and not w['image_candidate']];print('Additional source matches:',resolved);print('Still need a meaningful picture:',len(missing),' | '.join(missing))
if __name__=='__main__':main()
